	tableFixedPutF32(b[1169:], value.AimY)
	tableFixedPutF32(b[1173:], value.AimZ)
	tableFixedPutF32(b[1177:], value.Recoil)
	tableFixedPutF64(b[1181:], value.Drift)
	tableFixedPut128(b[1189:], value.WideKey.Lo, value.WideKey.Hi)
